      <label for="ht-plan-yearly">Yearly <span class="plan-save">save 20%</span></label>
    </div>
    <div class="plan-grid"><article class="plan-card" data-plan="free" data-monthly="0" data-yearly="0" data-year-total="0">
      <h2 class="plan-name">Free</h2>
      <p class="plan-who">For teams getting started at no cost.</p>
      <p class="plan-price"><span class="plan-amount">$0</span><span class="plan-unit">per seat, forever</span></p><p class="plan-detail">Free on monthly or yearly billing</p>
      <ul class="plan-points"><li>Unlimited members</li><li>Unlimited open tickets</li><li>Own up to 3 boards (archived boards do not count)</li><li>Small starter AI allowance</li></ul>
      <a class="plan-cta" href="https://app.hypertask.ai/login">Start free</a>
    </article><article class="plan-card" data-plan="byok" data-monthly="10" data-yearly="8" data-year-total="96">
      <h2 class="plan-name">BYOK</h2>
      <p class="plan-who">For teams that bring their own AI keys.</p>
      <p class="plan-price"><span class="plan-amount price-yearly">$8</span><span class="plan-amount price-monthly">$10</span><span class="plan-unit">per seat / month</span></p>
        <p class="plan-detail price-yearly">$96 per seat, billed yearly</p>
        <p class="plan-detail price-monthly">Billed every month</p>
        <p class="plan-alt price-yearly">or $10/seat/month billed monthly</p>
        <p class="plan-alt price-monthly">or $8/seat/month billed yearly ($96/yr)</p>
      <ul class="plan-points"><li>Use your own AI keys</li><li>Email support</li><li>14-day trial</li></ul>
      <a class="plan-cta" href="https://app.hypertask.ai/login">Start 14-day trial</a>
    </article><article class="plan-card" data-plan="pro" data-monthly="20" data-yearly="16" data-year-total="192">
      <h2 class="plan-name">Pro</h2>
      <p class="plan-who">For teams that want managed AI, with no keys.</p>
      <p class="plan-price"><span class="plan-amount price-yearly">$16</span><span class="plan-amount price-monthly">$20</span><span class="plan-unit">per seat / month</span></p>
        <p class="plan-detail price-yearly">$192 per seat, billed yearly</p>
        <p class="plan-detail price-monthly">Billed every month</p>
        <p class="plan-alt price-yearly">or $20/seat/month billed monthly</p>
        <p class="plan-alt price-monthly">or $16/seat/month billed yearly ($192/yr)</p>
      <ul class="plan-points"><li>Managed AI models, no keys to manage</li><li>Integrations</li><li>Priority support</li><li>14-day trial</li></ul>
      <a class="plan-cta" href="https://app.hypertask.ai/login">Start 14-day trial</a>
    </article></div>
    <p class="plan-note">Paid plans include a 14-day trial and are offered for up to 50 seats. For more than 50 seats, email <a href="mailto:help@hypertask.ai">help@hypertask.ai</a>.</p>
  </section>"}
